import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';
import { configuration, measure, statistics } from '../../tools/bench/measure.mjs';
import { parseOptions } from '../../tools/bench/numeric.mjs';

// Independent i32 Euclid fixture: sufficient only for this probe's small inputs.
// Not generated by or presented as evidence about the source compiler.
function gcdWasm() {
  const section = (id, bytes) => [id, bytes.length, ...bytes];
  const body = [1, 3, 0x7f, // three i32 locals after two f64 parameters
    0x20, 0, 0x99, 0xab, 0x21, 2, 0x20, 1, 0x99, 0xab, 0x21, 3,
    0x02, 0x40, 0x03, 0x40, 0x20, 3, 0x45, 0x0d, 1,
    0x20, 2, 0x20, 3, 0x70, 0x21, 4,
    0x20, 3, 0x21, 2, 0x20, 4, 0x21, 3, 0x0c, 0, 0x0b, 0x0b,
    0x20, 2, 0xb8, 0x0b];
  const bytes = new Uint8Array([0, 97, 115, 109, 1, 0, 0, 0,
    ...section(1, [1, 0x60, 2, 0x7c, 0x7c, 1, 0x7c]), ...section(3, [1, 0]),
    ...section(7, [1, 3, 114, 117, 110, 0, 0]), ...section(10, [1, body.length, ...body])]);
  assert.ok(WebAssembly.validate(bytes));
  return bytes;
}

test('probe configuration is bounded and CLI options cannot silently fall back', () => {
  assert.deepEqual(configuration(), { samples: 9, iterations: 100_000, warmup: 5000 });
  assert.equal(parseOptions(['--samples', '2', '--warmup', '0']).warmup, 0);
  for (const args of [['--other', '1'], ['constructor', 'x'], ['--compiler'],
    ['--samples', '2', '--samples', '3'], ['--samples', '2junk'], ['--warmup', '-1'],
    ['--samples', '1'], ['--samples', '51'], ['--iterations', '0'], ['--iterations', '1000001']]) {
    assert.throws(() => parseOptions(args), undefined, JSON.stringify(args));
  }
});

test('statistics retain raw sample order and calculate even and odd medians', () => {
  const samples = [10, 1, 4, 3];
  const result = statistics(samples);
  assert.deepEqual(result, { samplesMs: samples, minMs: 1, medianMs: 3.5, maxMs: 10 });
  result.samplesMs[0] = 99;
  assert.equal(samples[0], 10);
  assert.equal(statistics([0, 7, 2]).medianMs, 2);
  for (const bad of [[], [NaN], [-1], [Infinity]]) assert.throws(() => statistics(bad), RangeError);
});

test('measurements retain provenance-independent correctness and raw samples', async () => {
  const source = await readFile(new URL('../../examples/numeric-workflow/gcd.js', import.meta.url), 'utf8');
  const report = await measure(gcdWasm(), source, { samples: 3, iterations: 17, warmup: 9 });
  assert.deepEqual(report.config, { samples: 3, iterations: 17, warmup: 9 });
  assert.equal(report.checksum, 163);
  assert.equal(report.cases.length, 8);
  for (const value of Object.values(report.startup)) assert.ok(Number.isFinite(value) && value >= 0);
  for (const engine of ['js', 'wasm']) {
    const result = report.batches[engine];
    assert.equal(result.samplesMs.length, 3);
    assert.deepEqual(result, statistics(result.samplesMs));
  }
  await assert.rejects(measure(gcdWasm(), 'export function run(a,b) { return a+b; }', {}), /mismatch/);
  await assert.rejects(measure(new Uint8Array(), source, {}), WebAssembly.CompileError);
});
